+        match literal_expr {
+            LiteralExpressionRef::StringLiteral(ExprStringLiteral { value, .. }) => {
+                let string_value = value.to_str();
+                allowed_values.iter().any(|allowed| {
+                    if let AllowedValue::String(s) = allowed {
